#include <flatbuffers/flatbuffers.h>
#include "json.hpp"

using namespace flatbuffers;
using namespace std;

std::unique_ptr<flatbuffers::Verifier> vrf = flatbuffers::Verifier::Create();

void ConvertFlatBufferToJson(const char* root_table, vector<std::string>& json_data) {
    flatbuffers::Vector<const char*> buffer = {root_table};
    flatbuffers::Offset<Table> table = Table::Reader(buffer).GetRoot();

    auto builder = std::make_unique<flatbuffers::FlatBufferBuilder>(table.ByteSize());
    table.WriteTo(builder.get(), false);

    auto parsed_json = nlohmann::json::parse(std::string_view(reinterpret_cast<char*>(builder->Finish())), nullptr, false); // parse as non-strict

    for (const auto& str : json_data)
        parsed_json[str] = "converted_to_json";

    std::stringstream ss;
    ss << parsed_json.dump(4);
    return ss.str();
}

